<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref,shallowRef,watch} from 'vue';import {useRouter} from 'vue-router';import {ArrowRight,ExternalLink} from 'lucide-vue-next';import MathText from './MathText.vue';
defineOptions({inheritAttrs:false});
const props=withDefaults(defineProps<{html:string;notes?:any[];terms?:Record<string,any>;className?:string}>(),{notes:()=>[],terms:()=>({})});const router=useRouter(),container=ref<HTMLElement>(),card=ref<HTMLElement>(),active=shallowRef<any>(null),pinned=ref(false),pos=ref<{left:number;top:number}|null>(null);let openTimer:ReturnType<typeof setTimeout>,closeTimer:ReturnType<typeof setTimeout>,frame=0;const byNumber=computed(()=>new Map(props.notes.map(n=>[String(n.n),n])));
function close(){clearTimeout(openTimer);clearTimeout(closeTimer);pinned.value=false;active.value=null;}
function show(element:HTMLElement,immediate=false){clearTimeout(closeTimer);clearTimeout(openTimer);const payload=element.dataset.term?{term:props.terms[element.dataset.term]}:{note:byNumber.value.get(element.dataset.note!)};if(!payload.term&&!payload.note)return;const reveal=()=>active.value={element,...payload};if(immediate)reveal();else openTimer=setTimeout(reveal,70);}
function keepOpen(){clearTimeout(closeTimer);}
function hide(){clearTimeout(openTimer);if(!pinned.value){clearTimeout(closeTimer);closeTimer=setTimeout(()=>active.value=null,140);}}
function marker(event:Event){return (event.target as Element)?.closest<HTMLElement>('[data-note],[data-term]');}
function over(e:Event){const m=marker(e);if(m)show(m);}function out(e:Event){if(marker(e))hide();}function focus(e:Event){const m=marker(e);if(m)show(m,true);}
function click(e:MouseEvent){const m=marker(e);if(!m)return;if(m.dataset.term){const href=m.getAttribute('href');if(href?.startsWith('/')&&e.button===0&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey){e.preventDefault();close();router.push(href);}return;}e.preventDefault();if(active.value?.element===m&&pinned.value)close();else{show(m,true);pinned.value=true;}}
function key(e:KeyboardEvent){if(e.key==='Escape')close();else if((e.key==='Enter'||e.key===' ')&&marker(e)&&!marker(e)?.dataset.term){e.preventDefault();const m=marker(e)!;if(active.value?.element===m&&pinned.value)close();else{show(m,true);pinned.value=true;}}}
function outside(e:Event){if(active.value&&!card.value?.contains(e.target as Node)&&!active.value.element.contains(e.target))close();}
function place(){const anchor=active.value?.element.getBoundingClientRect();if(!anchor)return;const w=card.value?.offsetWidth??Math.min(320,innerWidth-16),h=card.value?.offsetHeight??140;const above=anchor.top>h+16;pos.value={left:Math.min(Math.max(8,anchor.left+anchor.width/2-w/2),innerWidth-w-8),top:Math.min(Math.max(8,above?anchor.top-h-8:anchor.bottom+8),innerHeight-h-8)};}
watch(active,async value=>{cancelAnimationFrame(frame);if(!value){pos.value=null;return;}place();await nextTick();frame=requestAnimationFrame(place);});watch(()=>props.html,close);
onMounted(()=>{document.addEventListener('keydown',key);document.addEventListener('pointerdown',outside);window.addEventListener('scroll',place,true);window.addEventListener('resize',place);});onBeforeUnmount(()=>{close();cancelAnimationFrame(frame);document.removeEventListener('keydown',key);document.removeEventListener('pointerdown',outside);window.removeEventListener('scroll',place,true);window.removeEventListener('resize',place);});
</script><template><div ref="container" v-bind="$attrs" :class="className" v-html="html" @mouseover="over" @mouseout="out" @focusin="focus" @focusout="out" @click="click"/><Teleport v-if="active&&pos" to="body"><div ref="card" role="tooltip" @mouseenter="keepOpen" @mouseleave="hide" :style="{position:'fixed',left:pos.left+'px',top:pos.top+'px',width:'320px',maxWidth:'calc(100vw - 16px)',maxHeight:'45vh',overflowY:'auto'}" class="z-30 rounded-token-md border border-line bg-surface-raised px-3.5 py-3 text-left text-token-xs leading-relaxed shadow-token-md"><template v-if="active.note"><span class="block text-ink"><span class="font-accent tabular-nums text-ink-faint">{{active.note.n}}</span><span v-if="active.note.label" class="ml-2">{{active.note.label}}</span></span><span v-if="active.note.kind==='note'&&active.note.text" class="mt-1.5 block text-ink-muted">{{active.note.text}}</span><span v-if="active.note.quote" class="mt-1.5 block border-l-2 border-line pl-2 text-ink-muted">{{active.note.quote}}</span><span v-if="active.note.quoteZh" class="mt-1.5 block border-l-2 border-line pl-2 text-ink-muted"><span class="mr-1 font-accent text-token-xs uppercase tracking-[0.12em] text-ink-faint">中譯</span>{{active.note.quoteZh}}</span><span v-if="active.note.kind!=='note'&&active.note.text" class="mt-1.5 block text-ink-muted">{{active.note.text}}</span><span v-if="active.note.locator" class="mt-1.5 block text-ink-faint"><MathText :text="active.note.locator"/></span><a v-if="active.note.href" :href="active.note.href" target="_blank" rel="noreferrer" class="mt-2 inline-flex items-center gap-1 text-accent hover:underline">原文<ExternalLink :size="11"/></a></template><template v-else><span class="block font-medium text-ink">{{active.term.term}}</span><span v-if="active.term.kind" class="mt-0.5 block font-accent text-token-xs uppercase tracking-[0.1em] text-ink-faint">{{active.term.kind}}</span><span class="mt-1.5 block text-ink-muted">{{active.term.oneLine}}</span><a v-if="active.term.route" :href="active.term.route" class="mt-2 inline-flex items-center gap-1 text-accent hover:underline">完整說明<ArrowRight :size="11"/></a></template></div></Teleport></template>
